// Ensure rows exists
const players = msg.payload.rows || [];

// Build simplified player list
const playerList = players.map(player => ({
    name: player.name,
    model: player.productName,
    resolution: `${player.width} x ${player.height}`,
    onlineStatus: player.onlineStatus === 1 ? "Online" : "Offline",
    lastSeen: player.lastOnlineTime
}));

// Create a complete payload
