});

return msg;

// Accept MQTT payload as JSON or string
let data = msg.payload;

// Convert string to object if needed
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (err) {
        node.error("Invalid JSON received from MQTT");
        return null;
    }
}

// Basic validation
if (!data || !Array.isArray(data.players)) {
    node.error("Invalid payload: players array missing");
    return null;
}

// Store latest payload
flow.set("latestPlayerData", data);

// Optional statistics
flow.set("playerCount", data.players.length);
flow.set(
    "onlineCount",
    data.players.filter(p => p.onlineStatus === "Online").length
);

flow.set(
    "offlineCount",
    data.players.filter(p => p.onlineStatus === "Offline").length
);

node.status({
    fill: "green",
    shape: "dot",
    text: `${data.players.length} players updated`
});

// Forward the message (optional)
msg.payload = data;

return msg;

// Store the latest payload globally
global.set("playerData", msg.payload);

